import React, { lazy, Suspense, useCallback, useEffect, useRef, useState } from 'react';
import { X, Plus, RefreshCw, ArrowUp, FolderOpen, Upload, PanelBottom, Maximize, Settings2, Server, Folder, FileText, FileCode2, Link2, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Minus, Square, Sun, Moon, Check, SquareTerminal } from 'lucide-react';
import { api, isPreview } from './api';
